      "element_id": "prisma_2020_5_e4",
      "status": "PRESENT",
      "chunk_id": "text_16",
      "quote": "Based on the study region, subgroup analyses were done.",
      "reason": "The manuscript specifies groups used in syntheses (subgroup analyses by study region) and uses these in the analyses, linking groupings (regions) to the syntheses."
    },
    {
      "element_id": "prisma_2020_5_e5",
      "status": "MISSING",
      "chunk_id": null,
      "quote": null,
      "reason": "The manuscript imposes restrictions (e.g., English language, date range) but does not provide rationales for these notable eligibility restrictions."
    }
  ],
  "confidence": "85"
}

